// API配置文件
const API_CONFIG = {
  // 基础URL
  BASE_URL: 'http://192.168.2.12:8000/api',

  // 超时时间
  TIMEOUT: 20000,

  // 请求头
  HEADERS: {
    'Content-Type': 'application/json',
    'Accept': 'application/json'
  }
};

export default API_CONFIG;
